local InkwellDustCoverMaker = {}
local PRODUCTS = {
    iron_inkwelldustcover = { name = "Železni prevleka za črnilnico", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni prevleka za črnilnico za pisarje." },
    bronze_inkwelldustcover = { name = "Bronast prevleka za črnilnico", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast prevleka za črnilnico za pisarje." },
    silver_inkwelldustcover = { name = "Srebrn prevleka za črnilnico", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn prevleka za črnilnico za pisarje." },
    gilded_inkwelldustcover = { name = "Pozlačen prevleka za črnilnico", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen prevleka za črnilnico za pisarje." },
    jewel_set_inkwelldustcover = { name = "Draguljast prevleka za črnilnico", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast prevleka za črnilnico za pisarje." },
    royal_sovereign_inkwelldustcover = { name = "Kraljevski suveren prevleka za črnilnico", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren prevleka za črnilnico z biseri za krono." },
}
local BUILDINGS = {
    inkwelldustcover_workshop = { name = "Inkwelldustcover delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    inkwelldustcover_house = { name = "Inkwelldustcover hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_inkwelldustcover_atelier = { name = "Mojstrski inkwelldustcover atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_inkwelldustcover_palace = { name = "Suverena inkwelldustcover palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
InkwellDustCoverMaker.ironStock=12; InkwellDustCoverMaker.bronzeStock=10; InkwellDustCoverMaker.woodStock=14; InkwellDustCoverMaker.leatherStock=14; InkwellDustCoverMaker.silverStock=8; InkwellDustCoverMaker.goldStock=6; InkwellDustCoverMaker.jewelStock=4; InkwellDustCoverMaker.pearlStock=4
InkwellDustCoverMaker.productStock = {}; InkwellDustCoverMaker.buildings = {}; InkwellDustCoverMaker.maker = nil; InkwellDustCoverMaker.activeMaking = {}; InkwellDustCoverMaker.totalProducts = 0; InkwellDustCoverMaker.dayTimer = 0
function InkwellDustCoverMaker.init() InkwellDustCoverMaker.ironStock=12; InkwellDustCoverMaker.bronzeStock=10; InkwellDustCoverMaker.woodStock=14; InkwellDustCoverMaker.leatherStock=14; InkwellDustCoverMaker.silverStock=8; InkwellDustCoverMaker.goldStock=6; InkwellDustCoverMaker.jewelStock=4; InkwellDustCoverMaker.pearlStock=4; InkwellDustCoverMaker.productStock={}; InkwellDustCoverMaker.buildings={}; InkwellDustCoverMaker.maker=nil; InkwellDustCoverMaker.activeMaking={}; InkwellDustCoverMaker.totalProducts=0; InkwellDustCoverMaker.dayTimer=0; print("[InkwellDustCoverMaker] Royal Inkwell Dust Cover Maker System initialized (6 products, 4 buildings)") end
function InkwellDustCoverMaker.hireMaker(n,s) s=s or math.random(55,90); local c=565+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; InkwellDustCoverMaker.maker={name=n or ("Prevlekar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Prevlekar najet: %s (spretnost: %d)",InkwellDustCoverMaker.maker.name,s),"success") end; return true end
function InkwellDustCoverMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function InkwellDustCoverMaker.build(id) local ok,e=InkwellDustCoverMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(InkwellDustCoverMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function InkwellDustCoverMaker.getQualityBonus() local b=0; for _,bd in ipairs(InkwellDustCoverMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function InkwellDustCoverMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and InkwellDustCoverMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and InkwellDustCoverMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and InkwellDustCoverMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and InkwellDustCoverMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and InkwellDustCoverMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and InkwellDustCoverMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and InkwellDustCoverMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and InkwellDustCoverMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #InkwellDustCoverMaker.buildings==0 then return false,"Potrebna prevlečna delavnica" end; if not InkwellDustCoverMaker.maker then return false,"Potreben prevlekar" end; return true end
function InkwellDustCoverMaker.make(pt,qty) qty=qty or 1; local ok,e=InkwellDustCoverMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then InkwellDustCoverMaker.ironStock=InkwellDustCoverMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then InkwellDustCoverMaker.bronzeStock=InkwellDustCoverMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then InkwellDustCoverMaker.woodStock=InkwellDustCoverMaker.woodStock-d.woodCost*qty end; if d.leatherCost then InkwellDustCoverMaker.leatherStock=InkwellDustCoverMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then InkwellDustCoverMaker.silverStock=InkwellDustCoverMaker.silverStock-d.silverCost*qty end; if d.goldCost then InkwellDustCoverMaker.goldStock=InkwellDustCoverMaker.goldStock-d.goldCost*qty end; if d.jewelCost then InkwellDustCoverMaker.jewelStock=InkwellDustCoverMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then InkwellDustCoverMaker.pearlStock=InkwellDustCoverMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if InkwellDustCoverMaker.maker then t=math.max(1,t-math.floor(InkwellDustCoverMaker.maker.skill/13)) end; table.insert(InkwellDustCoverMaker.activeMaking,{id="inkwelldustcover_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function InkwellDustCoverMaker.completeMaking(m) local q=1.0+(InkwellDustCoverMaker.getQualityBonus()/100); if InkwellDustCoverMaker.maker then q=q+(InkwellDustCoverMaker.maker.skill/140) end; q=math.min(2.5,q); InkwellDustCoverMaker.productStock[m.productType]=(InkwellDustCoverMaker.productStock[m.productType] or 0)+m.quantity; InkwellDustCoverMaker.totalProducts=InkwellDustCoverMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if InkwellDustCoverMaker.maker then InkwellDustCoverMaker.maker.itemsMade=InkwellDustCoverMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then InkwellDustCoverMaker.maker.skill=math.min(100,InkwellDustCoverMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Prevleka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"inkwelldustcover.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function InkwellDustCoverMaker.update(dt) if not _G.state then return end; InkwellDustCoverMaker.dayTimer=InkwellDustCoverMaker.dayTimer+dt; if InkwellDustCoverMaker.dayTimer>=30 then InkwellDustCoverMaker.dayTimer=0; for i=#InkwellDustCoverMaker.activeMaking,1,-1 do local m=InkwellDustCoverMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then InkwellDustCoverMaker.completeMaking(m); table.remove(InkwellDustCoverMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(InkwellDustCoverMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if InkwellDustCoverMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function InkwellDustCoverMaker.getStats() return {ironStock=InkwellDustCoverMaker.ironStock,bronzeStock=InkwellDustCoverMaker.bronzeStock,woodStock=InkwellDustCoverMaker.woodStock,leatherStock=InkwellDustCoverMaker.leatherStock,silverStock=InkwellDustCoverMaker.silverStock,goldStock=InkwellDustCoverMaker.goldStock,jewelStock=InkwellDustCoverMaker.jewelStock,pearlStock=InkwellDustCoverMaker.pearlStock,productStock=InkwellDustCoverMaker.productStock,numBuildings=#InkwellDustCoverMaker.buildings,hasMaker=InkwellDustCoverMaker.maker~=nil,makerName=InkwellDustCoverMaker.maker and InkwellDustCoverMaker.maker.name or "—",makerSkill=InkwellDustCoverMaker.maker and InkwellDustCoverMaker.maker.skill or 0,activeMaking=#InkwellDustCoverMaker.activeMaking,totalProducts=InkwellDustCoverMaker.totalProducts} end
return InkwellDustCoverMaker
